SELECT
  extensions.uuid_generate_v5(extensions.uuid_ns_url(), $q$abubae:practical:jeongchogi-practical-2025-2-020$q$), id, 'practical', 2025, 2, $q$실기$q$, 20,
  $q$다음 C 언어로 구현된 프로그램을 분석하여 그 실행 결과를 쓰시오. (단, 출력문의 출력
서식을 준수하시오.) (5점)
#include <stdio.h>
#include <stdlib.h>
struct node {
char c;
struct node* p;
};
struct node* func(char* s) {
struct node* h = NULL, *n;
while(*s) {
n = malloc(sizeof(struct node));
n -> c = *s++;
n -> p = h;
h = n;
}
return h;
}
int main( ) {
struct node* n = func("BEST");
while(n) {
putchar(n -> c);
struct node* t = n;
n = n -> p;
free(t);
}
return 0;
}$q$, $q$#include <stdio.h>
#include <stdlib.h>
struct node { // 구조체 node를 정의한다.
char c; // 문자형 변수 c를 선언한다.
struct node* p; // node의 구조체 포인터 변수 p를 선언한다.
struct node
char c (1Byte) struct node* p (4Byte)
데이터를 저장할 멤버 다음 노드의 주소를 저장할 멤버
};
int main( ) {
❶ struct node* n = func("BEST");
while(n) {
putchar(n -> c);
struct node* t = n;
n = n -> p;
free(t);
}
return 0;
}
모든 C 언어 프로그램은 반드시 main( ) 함수에서 시작한다.
❶ node 자료형 포인터 변수 n을 선언하고, “BEST”를 인수로 func( ) 함수를 호출한 후 반환받은 값으로 초
기화한다.
